CREATE FUNCTION public.has_employee_clock_access(_employee uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workforce_schedules s JOIN public.organizations o ON o.id=s.org_id JOIN public.profiles p ON p.user_id=s.employee_id AND p.org_id=s.org_id WHERE s.employee_id=_employee AND s.enabled AND p.deleted_at IS NULL AND lower(p.status)='active' AND 'attendance'=ANY(o.enabled_modules)) $$;
REVOKE ALL ON FUNCTION public.has_employee_clock_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_employee_clock_access(uuid) TO authenticated,service_role;